mapper.select:
SELECT disposable_key, object_type, object_id, file_no, file_name, user_cd, session_id
  FROM docs_viewer_key
 WHERE disposable_key = #{key}
   AND user_cd = #{userCd}
   AND session_id = #{sessionId}
   AND revoked_yn = 'N'
   AND used_at IS NULL
   AND delete_at > CURRENT_TIMESTAMP

mapper.update:
UPDATE docs_viewer_key
   SET used_at = CURRENT_TIMESTAMP
 WHERE disposable_key = #{key}
   AND user_cd = #{userCd}
   AND session_id = #{sessionId}
   AND revoked_yn = 'N'
   AND used_at IS NULL
   AND delete_at > CURRENT_TIMESTAMP
